```python
def most_common_char(s):
    if not s:
        return ''
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    best_char = s[0]
    best_count = counts[s[0]]
    for ch in s:
        if counts[ch] > best_count or (counts[ch] == best_count and s.index(ch) < s.index(best_char)):
            best_char = ch
            best_count = counts[ch]
    return best_char
```

